import subprocess, re
files = subprocess.check_output(['git','diff','--name-only'], text=True).splitlines()
tell = re.compile(r'主人|钦定|老板|拍板|定案|开干|结案|bus#|群#|野花令|按谁|令：|令:')
logic = []
wording = []
for f in files:
    diff = subprocess.check_output(['git','diff','-U0','--', f], text=True, errors='replace')
    hunks = []
    bad = False
    reasons = []
    for line in diff.splitlines():
        if line.startswith(('+++','---','@@','diff','index')):
            continue
        if line[:1] not in '+-':
            continue
        body = line[1:]
        stripped = body.strip()
        if not stripped:
            continue
        if tell.search(stripped):
            continue
        # leftover punctuation-only from a wording strip on same conceptual line is ok if short
        if stripped in {'--', '#', '"""', "'''"}:
            continue
        bad = True
        if len(reasons) < 3:
            reasons.append(line[:180])
    if bad:
        logic.append((f, reasons))
    else:
        wording.append(f)
print(f'wording={len(wording)} logic={len(logic)}')
print('--- logic files ---')
for f, reasons in logic:
    print(f)
    for r in reasons:
        print('   ', r)
PY
